import { parentPort } from 'node:worker_threads';
import { IverilogWasmError } from './errors.js';
import { WORKER_PROTOCOL_VERSION, } from './protocol.js';
import { compileRuntime, runRuntime, simulateRuntime } from './runtime.js';
if (parentPort === null) {
    throw new IverilogWasmError('WORKER_START', 'The worker module must run in a Node worker thread.');
}
function serializeError(error) {
    if (error instanceof Error) {
        return {
            name: error.name,
            message: error.message,
            ...(error.stack === undefined ? {} : { stack: error.stack }),
            ...(error instanceof IverilogWasmError ? { code: error.code } : {}),
        };
    }
    return {
        name: 'Error',
        message: String(error),
    };
}
function serializeResult(result) {
    if ('artifacts' in result) {
        return {
            ...result,
            artifacts: [...result.artifacts],
        };
    }
    return result;
}
function outputTransfers(result) {
    const transfers = new Set();
    if ('program' in result && result.program?.buffer instanceof ArrayBuffer) {
        transfers.add(result.program.buffer);
    }
    if ('artifacts' in result) {
        for (const [, artifact] of result.artifacts) {
            if (artifact.buffer instanceof ArrayBuffer) {
                transfers.add(artifact.buffer);
            }
        }
    }
    return [...transfers];
}
async function handleRequest(request) {
    if (request.protocol !== WORKER_PROTOCOL_VERSION) {
        throw new IverilogWasmError('PROTOCOL_MISMATCH', `Unsupported worker protocol version: ${String(request.protocol)}.`);
    }
    let result;
    switch (request.action) {
        case 'compile':
            result = await compileRuntime(request.payload);
            break;
        case 'run':
            result = await runRuntime(request.payload);
            break;
        case 'simulate':
            result = await simulateRuntime(request.payload);
            break;
        default:
            throw new IverilogWasmError('PROTOCOL_MISMATCH', 'Worker received an unknown action.');
    }
    const serialized = serializeResult(result);
    const reply = {
        protocol: WORKER_PROTOCOL_VERSION,
        id: request.id,
        kind: 'result',
        result: serialized,
    };
    parentPort.postMessage(reply, outputTransfers(serialized));
}
parentPort.on('message', (value) => {
    const request = value;
    void handleRequest(request).catch(error => {
        const reply = {
            protocol: WORKER_PROTOCOL_VERSION,
            id: typeof request?.id === 'string' ? request.id : '',
            kind: 'error',
            error: serializeError(error),
        };
        parentPort.postMessage(reply);
    });
});
